select 1 / case when exists(select 1 from pg_proc where oid='public.spec_validate_product_member_profiles_internal_v1(uuid)'::regprocedure and md5(pg_get_functiondef(oid))='51736f7297cc9dfe673e2f8df15d5bcb' and pg_get_userbyid(proowner)='postgres' and not prosecdef and provolatile='s' and proconfig=array['search_path=pg_catalog, public, pg_temp']::text[] and proacl=array['postgres=X/postgres','service_role=X/postgres']::aclitem[]) then 1 else 0 end as member_issue_details_match;
